const bars=normalizeBars({bars:read('analyses/TSM/_data/bars.json').results[0].data[0].bars},ticker,EQUITY_CALENDAR);
if(bars.at(-1).date!==ref) throw Error('reference close missing');
const close=bars.at(-1).close, prev=bars.at(-2).close, change=(close/prev-1)*100;
const perf=n=>{const a=bars.at(-(n+1));return a?(close/a.close-1)*100:null};
const closeOn=date=>bars.find(x=>x.date===date)?.close;
const technical=read('analyses/TSM/_data/technicals.json').data.items[0].results.find(x=>x.data_type==='technicals').data[0];
const fundResults=read('analyses/TSM/_data/fundamentals.json').data.items[0].results;
const facet=t=>fundResults.find(x=>x.data_type===t)?.data?.[0]||{};
const f=facet('financials'), stats=facet('stats'), cal=facet('calendar'), surprises=facet('earnings_surprises');
const quarters=facet('earnings_quarterly')||[];
const audit=read('analyses/TSM/_review/parent-comparison-audit.json');
const auditByTicker=new Map((audit.comparisons||[]).map(row=>[row.ticker,row]));
const comparisonContext=read('analyses/TSM/_data/comparison_context.json');
