const contextResults=comparisonContext.data?.items?.[0]?.results||[];
const comparisonCalendars=contextResults.find(row=>row.data_type==='calendar')?.data||[];
const calendarByTicker=new Map(comparisonCalendars.map(row=>[row.symbol,row]));
const etfTickers=new Set(['SMH','SOXX']);
const comparisonEventNote=(comparisonEarnings.events||[]).length===0?'comparison_earnings ne contient aucun événement complémentaire.':'comparison_earnings contient des événements complémentaires à relire séparément.';
const eventWindow='du 12 au 25 septembre';
const formatEventDate=value=>new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(value));
function comparisonEventRisk(symbol){
 if(etfTickers.has(symbol)) return `ETF : pas de résultats corporatifs. La collecte ${comparisonEventNote} Le risque vient du panier, pas d’une publication d’émetteur.`;
 const row=calendarByTicker.get(symbol);
 if(!row?.nextEarningsDate) return `Calendrier de résultats indisponible dans comparison_context; ${comparisonEventNote} Risque événementiel non quantifié.`;
 return `Calendrier secondaire disponible : prochaine date de résultats estimée le ${formatEventDate(row.nextEarningsDate)}. Elle est hors de la fenêtre de suivi ${eventWindow}; ${comparisonEventNote}`;
}
function bl(ticker,role,relationClass,order,readThrough){
 const m=auditByTicker.get(ticker); if(!m) throw Error(`audit missing ${ticker}`);
 const unavailable=m.status!=='PASS';
 return {ticker,role,relationClass,confidence:unavailable?'low':'high',return5d:m.return5d?.value??null,return21d:m.return21d?.value??null,correlation:m.correlation??null,beta:m.beta??null,r2:m.r2??null,observations:m.observations??null,readThrough:unavailable?`${readThrough} Régression indisponible : séances de juillet manquantes dans la série certifiée.`:readThrough,eventRisk:comparisonEventRisk(ticker)}
}
const entry=426, stop=408.09, tp1=465.73;
const realizedEps=quarters.reduce((sum,q)=>sum+Number(q.actual||0),0), realizedPe=close/realizedEps;
// Fenêtre strictement post-publication T2 : même BPA ADS réalisé sur chaque clôture, pas de moyenne de cycle ni d'EPS annuel non rapproché.
const historicalPeStart='2026-07-17', historicalPeBars=bars.filter(bar=>bar.date>=historicalPeStart&&bar.date<=ref);
if(historicalPeBars.length===0) throw Error('post-Q2 P/E window empty');
const historicalPes=historicalPeBars.map(bar=>bar.close/realizedEps).sort((left,right)=>left-right);
const median=values=>{const midpoint=Math.floor(values.length/2); return values.length%2?values[midpoint]:(values[midpoint-1]+values[midpoint])/2};
const historicalPe={start:historicalPeStart,end:ref,sessions:historicalPeBars.length,rollingEpsAds:realizedEps,min:historicalPes[0],median:median(historicalPes),max:historicalPes.at(-1),closeAug28:closeOn('2026-08-28'),peAug28:closeOn('2026-08-28')/realizedEps,current:realizedPe,currentPercentile:historicalPes.filter(value=>value<=realizedPe).length/historicalPes.length*100};
if(!historicalPe.closeAug28) throw Error('2026-08-28 close missing');
// Projection explicitly hypothétique: guidance T3 officielle à 32 TWD/USD, 1 ADS=5 actions ordinaires selon le 20-F.
