const scenarioEv=scenarioMultiple*scenarioEbitda, scenarioEquity=scenarioEv-scenarioDebt+scenarioCash, scenarioPrice=scenarioEquity/scenarioShares, scenarioDownside=(scenarioPrice/close-1)*100;

